Item.method_code:
return window.ModulesManager.using(
	['aras.innovator.core.ItemWindow/DefaultItemWindowView',
	'aras.innovator.core.ItemWindow/DefaultItemWindowCreator'], function(View, Creator) {
		const itemTypeName = inDom.getAttribute('type');
		const viewMode = inArgs.viewMode || 'tab view';

		if (viewMode.search(/^tab view$|^openFile$|^new$/) == -1) {
			aras.AlertError(aras.getResource('', 'ui_methods_ex.specified_view_mode_invalid', viewMode), '', '');
		}

		if (viewMode === 'tab view' || viewMode === 'new') {
			const view = new View(inDom, inArgs);
			const creator = new Creator(view);
			return creator.ShowView();
		}

		aras.uiOpenEmptyWindowEx(inDom);
	});
